def build_instance(rng):
    set_size = rng.randint(3, 8)
    answer = math.comb(set_size, 3)
    edges = list(itertools.combinations(range(set_size), 2))
    check = 0
    for mask in range(1 << len(edges)):
        chosen = {edge for index, edge in enumerate(edges) if mask >> index & 1}
        triangle_free = all((not {(i, j), (i, k), (j, k)} <= chosen for i, j, k in itertools.combinations(range(set_size), 3)))
        if triangle_free:
            check = max(check, len(chosen))
    assert answer == check, f'answer={answer} check={check}'
    parameters = {'set_size': set_size}
    return (parameters, answer, check)



