    # Using the Cardano's method for solving cubic equations
    # ax^3 + bx^2 + cx + d = 0
    p = (3 * a * c - b**2) / (3 * a**2)
    q = (2 * b**3 - 9 * a * b * c + 27 * a**2 * d) / (27 * a**3)
    discriminant = (q / 2)**2 + (p / 3)**3
    if discriminant > 0:
        # One real root and two complex roots
        u = (-q / 2 + math.sqrt(discriminant)) ** (1/3)
        v = (-q / 2 - math.sqrt(discriminant)) ** (1/3)
        x1 = u + v - b / (3 * a)
        x2 = -(u + v) / 2 - b / (3 * a) + (u - v) * 3**0.5 * 0.5j
        x3 = -(u + v) / 2 - b / (3 * a) - (u - v) * 3**0.5 * 0.5j
        return {x1, x2, x3}
