def build_instance(rng):
    total_elements = rng.randint(1, 10)
    max_size = rng.randint(1, total_elements)
    answer = math.comb(total_elements, max_size)
    check = 0
    for size in range(1, max_size + 1):
        check += math.comb(total_elements, size)
    assert answer == check, f'answer={answer} check={check}'
    parameters = {'max_size': max_size, 'total_elements': total_elements}
    return (parameters, answer, check)



