import itertools
import math

def build_instance(rng):
    vertex_count = rng.randint(3, 5)
    color_count = rng.randint(2, vertex_count)
    answer = math.comb(vertex_count, 2) * math.comb(color_count, 2)
    edges = list(itertools.combinations(range(vertex_count), 2))
    check = 0
    for mask in range(1 << len(edges)):
        chosen = {edge for index, edge in enumerate(edges) if mask >> index & 1}
        valid_colorings = 0
        for coloring in itertools.product(range(color_count), repeat=vertex_count):
            if all((coloring[i] != coloring[j] for i, j in chosen)):
                valid_colorings += 1
        check = max(check, valid_colorings)
    assert answer == check, f'answer={answer} check={check}'
